using System;using System.IO;using System.Reflection;
class ReleaseCheck {
 static int Main(string[] args){string folder=null;try{if(args.Length!=2)throw new IOException("manifest and archive are required");var release=UpdatePolicy.Read(File.ReadAllText(args[0]),UpdateKey.PublicKey,new Version(0,0,0),BuildInfo.Repository);if(release.Version!=BuildInfo.Version)throw new IOException("Source and release version differ");UpdatePolicy.ValidateFile(args[1],release);folder=Path.Combine(Path.GetTempPath(),"WidgetReleaseCheck-"+Guid.NewGuid().ToString("N"));UpdatePolicy.Extract(args[1],folder);if(AssemblyName.GetAssemblyName(Path.Combine(folder,"CodexUsageWidget.exe")).Version!=new Version(release.Version+".0"))throw new IOException("Executable version differs");Console.WriteLine("VALID "+release.Version);return 0;}catch(Exception e){Console.WriteLine("INVALID "+e.Message);return 1;}finally{if(folder!=null&&Directory.Exists(folder)){foreach(string name in UpdatePolicy.AllowedFiles){string f=Path.Combine(folder,name);if(File.Exists(f))File.Delete(f);}Directory.Delete(folder,false);}}}
}
